VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.95,"Lecture one. Nature-inspired computing. This is how evolution became a way of solving problems."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":25.008,"caps":[[0.5,9.87,"Evolution: the fitter ones survive and breed."],[10.12,14.21,"Brains: useful connections get stronger."],[14.46,18.47,"Ants: short trails get more scent."],[18.72,23.37,"No one is in charge. Today: evolution."]],"warp":[[0,0],[0.5,0.5],[10.12,3.5],[14.46,6.5],[18.72,10],[25.008,12]]},{"dur":21.664,"caps":[[0.5,8.19,"Goal: turn QZT into CAT. Score = letters right."],[8.44,12.69,"Change one letter at random. Not worse? Keep it."],[12.94,16.07,"Worse? Throw it away."],[16.32,20.73,"Progress adds up. That is cumulative selection."]],"warp":[[0,0],[0.5,0.4],[8.44,2.4],[12.94,4.8],[16.32,6.6],[21.664,10]]},{"dur":33.344,"caps":[[0.5,4.75,"Same target. Same number of tries."],[5,8.37,"The monkey starts from scratch every time."],[8.62,12.55,"Keep-if-better locks in each correct letter."],[12.8,17.61,"The monkey's best is still 6 of 28."],[17.86,24.75,"27 choices for each of 28 places: 27 × 27 × … × 27."],[25,31.57,"Monkey: 1.2 × 10⁴⁰ tries on average. Keeper: 3,037."]],"warp":[[0,0],[0.5,0.4],[5,2.8],[8.62,6.2],[12.8,9.5],[17.86,10.8],[25,12.6],[33.344,15]]},{"dur":26.656,"caps":[[0.5,4.91,"A landscape: height is how good."],[5.16,9.09,"One climber keeps a step if it is not worse."],[9.34,12.47,"Stuck on the first hill."],[12.72,15.85,"Twenty climbers spread out and compete."],[16.1,25.87,"Each square is one run. More climbers find the top."]],"warp":[[0,0],[0.5,0.4],[5.16,1.9],[9.34,4.3],[12.72,5.8],[16.1,10.3],[26.656,13]]},{"dur":26.657,"caps":[[0.5,4.83,"Four parents with fitness 9, 6, 3 and 1."],[5.08,10.05,"Fitter parents are likelier to be picked, 20 times."],[10.3,14.31,"Only the best? Everyone becomes a copy."],[14.56,18.89,"Equal chances? Nothing pushes towards better."],[19.14,24.99,"Weak bias: fitter is likelier, nobody is shut out."]],"warp":[[0,0],[0.5,0.4],[5.08,2.8],[10.3,6.2],[14.56,8.2],[19.14,10.1],[26.657,12]]},{"dur":13.351,"caps":[[0.5,4.43,"Mutation: copy a parent, change one gene."],[4.68,8.13,"Recombination: mix pieces of two parents."],[8.38,12.71,"Mutation is needed. Recombination often helps."]],"warp":[[0,0],[0.5,0.4],[4.68,5.2],[8.38,8.9],[13.351,12]]},{"dur":25.008,"caps":[[0.5,4.35,"Score every dot: height is fitness."],[4.6,10.13,"Pick parents: the fitter, the likelier."],[10.38,13.11,"Optional: mix two parents."],[13.36,16.89,"Mutate: nudge each child a little."],[17.14,19.79,"The children become the new population."],[20.04,23.33,"Repeat: the dots climb towards the star."]],"warp":[[0,0],[0.5,0.4],[4.6,3.1],[10.38,5.1],[13.36,7.1],[17.14,8.8],[20.04,10.4],[25.008,13]]},{"dur":20.086,"caps":[[0.5,7.23,"Score = green boxes. An EA only needs a score."],[7.48,15.57,"Six areas, one requirement: you can score it."],[15.82,19.11,"Anything you can score, you can evolve."]],"warp":[[0,0],[0.5,0.4],[7.48,5.4],[15.82,8.8],[20.086,12]]},{"dur":13.235,"caps":[],"warp":[[0,0],[0.5,0.9],[4.04,1.9],[9.42,2.9],[13.235,9]]}]};
